INSERT INTO `generalinfo` (`id`, `Name`, `Detail`, `ImageURL`, `URL`) VALUES
(1, 'Shipping', '<p>All items are made-to-order. This means that when you place your order, we make that item just for you, one at a time, for the best quality!</p>\r\n\r\n<p>We process orders on business days, which are Monday through Friday, Eastern Standard-Times. We exclude holidays observed by the Post Office:&nbsp;New Year&rsquo;s Day,&nbsp;Presidents&rsquo; Day,&nbsp;Memorial Day,&nbsp;Independence Day,&nbsp;Labor Day,&nbsp;Thanksgiving, and&nbsp;Christmas.</p>\r\n\r\n<p>The time frame for order delivery is divided into two parts:</p>\r\n\r\n<p>Processing time:</p>\r\n\r\n<p>Orders will be shipped from Vietnam</p>\r\n\r\n<p>The majority of orders are produced and shipped within 7-10 business days.</p>\r\n\r\n<p>With custom orders such as: Pokemon keycaps, custom wrist rest&hellip; the processing time is 3 &ndash; 4 weeks.</p>\r\n\r\n<p>Shipping time:</p>\r\n\r\n<p>🇺🇸 United States:</p>\r\n\r\n<p>Economy: 8 -15 business days</p>\r\n\r\n<p>🇨🇦 Canada:</p>\r\n\r\n<p>Economy: 12 - 20 business days.</p>\r\n\r\n<p>🇬🇧 United Kingdom:</p>\r\n\r\n<p>Economy: 10 - 15 business days.</p>\r\n\r\n<p>🇦🇺 Australia &amp; New Zealand:</p>\r\n\r\n<p>Economy: 15 - 20 business days.</p>\r\n\r\n<p>🇪🇺 European Countries:</p>\r\n\r\n<p>Economy: 10 - 15 business days.</p>\r\n\r\n<p>Other Countries:&nbsp;</p>\r\n\r\n<p>Economy: 15 - 20 business days.</p>', NULL, NULL);
