INSERT INTO `products` (`IdProduct`, `NameProduct`, `TypeProduct`, `NewPrice`, `OldPrice`, `StatusProduct`, `ImageURL`, `Tag`, `Description`, `Category`, `SubCategory`, `updated_at`, `created_at`) VALUES
('arcanine-pokemon-keycap', 'Arcanine Pokemon Keycap', 'New Arrival', 29.5, 42.99, 'Publish', 'https://heroverseart.sgp1.cdn.digitaloceanspaces.com/assets/images/5FGArmBe_Arcanine-keycap-e1666184054821.jpg', 'Arcanine keycap, pokemon keycap, esc keycap, custom resin keycap, Charmander resin, dykeycap, Cherry MX keycap, mechanical keycap, keycap, keycaps, Arcanine custom, Arcanine resin', '<p><strong>Level up your Pokémon collection with Arcanine Pokemon keycap</strong></p>\r\n\r\n<p>The tiny Arcanine Pokemon keycap is cast in resin detailedly with 3 - 5 layers of paint color. The result is a Pokemon that look so lively and you can feel its unique power. Altogether, it creates a more diverse and interactive effect.</p>\r\n\r\n<p> </p>\r\n\r\n<p>In the generation that remote working becomes common, time spent at home increases. Having a unique, inspired piece added to your keyboard will help you be more relaxed and comfortable in computer working.</p>\r\n\r\n<p>The question is: which of these Pokémon will you choose as the signature Pokémon for your keyboard? Just let us know and we will create your personalized design.</p>\r\n\r\n<p><strong>The process of making an artisan keycap is complicated, but we enjoy it….</strong></p>\r\n\r\n<p>We always produce the keycap characters by casting them through shaped molds. We do not have them easily printed in 3D and just like that, the keycap details come straight out of a machine. Everything is done by the hands of our artisans, preparing the molds, pouring resin, and coloring the details.</p>\r\n\r\n<p>Ultimately, this painting step is hands down one of the hardest things we faced during the production of Heroverse. Pokemon molds in the collection are very small, so it’s very challenging to paint the Pokemon and keep them spirited as much as possible. We had to apply 3 - 5 layers of paint for each keycap so the colors can have a certain thickness and be clearer to our eyes.<br>\r\nWe hope you can wait patiently to receive our keycaps!<br>\r\n<br>\r\nMade from durable resin hand-painted in eye-popping colors by our artisans, each little toad is painted by hand to ensure it lives up to our high standards. This will obviously add some more inspiration to your work corner and keep you more creative to do what you love and love what you do.</p>\r\n\r\n<p>We’re open to any request you want on your personalized Pokemon key cap. Feel free to contact us.</p>\r\n\r\n<p>Specs:</p>\r\n\r\n<ul>\r\n	<li>Material: Resin</li>\r\n	<li>Profile: 1U</li>\r\n	<li>Compatible with Cherry MX switches</li>\r\n	<li>Designed and hand-painted by Heroverse</li>\r\n	<li>Handling time: about 3-4 weeks</li>\r\n	<li>Estimated shipping date: 3 weeks from the shipping date</li>\r\n</ul>', 'keycaps', 'pokemon-keycaps', '2025-12-16', '2025-12-16'),
('black-excalibur-sword-wrist-rest', 'Black Excalibur Sword Wrist Rest', 'New Arrival', 115, 150, 'Publish', 'https://heroverseart.sgp1.cdn.digitaloceanspaces.com/assets/images/4FyagEZN_excalibur-sword-wrist-rest-ver-2-3.jpg', 'mechanical keyboard, customizedkeycap, computer peripherals, keyboard periphelars, japanese art, wrist rest keycap, raised hands rest, keyboard wrist rest, handmade wrist rest, custom wrist rest, computer accessories, Excalibur sword, Excalibur Fate', '<p>Excalibur Sword Wrist Rest: Spicing up your whole room decor!</p>\r\n\r\n<p> </p>\r\n\r\n<p>Excalibur Morgan: Sword of Promised Victory, commonly known as Black Excalibur, is Excalibur\'s form after being corrupted by evil.</p>\r\n\r\n<p>However, it makes no difference whether it is loaded with good or corrupted by evil; the fact that it is the most powerful holy sword remains unchanged.</p>\r\n\r\n<p>Now fans of this powerful Black Sword of Ultimate Light can enjoy the legend in a whole new way with this fantastic Black Excalibur Sword Wrist Rest!</p>\r\n\r\n<p><img alt=\"Black excalibur sword wrist rest\" src=\"https://i0.wp.com/hirosarts.com/wp-content/uploads/2022/05/excalibur-sword-wrist-rest-ver-2-6.jpg?resize=644%2C448&amp;ssl=1\"></p>\r\n\r\n<p>Excalibur sword wrist rest 2</p>\r\n\r\n<p>The sword is no longer encased in Invisible Air and takes on a new look, becoming the \"Black Sword of Ultimate Light.\" Excalibur gathers a huge amount of magical energy to wrap the blade in black light as the magical colors put into our Stay Night Wrist rest.</p>\r\n\r\n<p>The Saber Alter\'s Sword Wrist rest is masterfully made, with excellent attention to detail and a delicate pattern. The enigmatic black light covered in this Black Excalibur sword Wrist Rest will surely be a highlight for your workspace.</p>\r\n\r\n<p><img alt=\"Black excalibur sword wrist rest\" src=\"https://i0.wp.com/hirosarts.com/wp-content/uploads/2022/05/excalibur-sword-wrist-rest-ver-2-4.jpg?resize=644%2C503&amp;ssl=1\"></p>\r\n\r\n<p>Black excalibur sword resin wrist rest</p>\r\n\r\n<p>Are you also interested in other legendary swords? Check out Heroverse <a href=\"https://heroverseart.com/catalog?category=wrist-rests\">wrist rest</a> for <a href=\"https://heroverseart.com/product/yellow-excalibur-sword-wrist-rest\">Yellow Excalibur sword Wrist Rest</a>, and other Japan Style wrist rests.</p>\r\n\r\n<p>Specs:</p>\r\n\r\n<p> </p>\r\n\r\n<ul>\r\n	<li>Size 60%: 30 x 1,5 x 2 (the thinnest place is 1.5 cm)</li>\r\n	<li>Size 65%: 32 x 1,5 x 2 (the thinnest place is 1.5 cm)</li>\r\n	<li>Size TKL: 36 x 1,5 x 2 (the thinnest place is 1.5 cm)</li>\r\n	<li>Full size: 44 x 1,5 x 2 (the thinnest place is 1.5 cm)</li>\r\n	<li>Material: Resin epoxy</li>\r\n	<li>Colors: Black and Red</li>\r\n	<li>Smooth, solvent-resistant polish for surface protection</li>\r\n</ul>\r\n\r\n<p>Inside the package:</p>\r\n\r\n<p> </p>\r\n\r\n<ul>\r\n	<li>1 wrist rest by Heroverse</li>\r\n	<li>1 card</li>\r\n</ul>\r\n\r\n<p>Sidenote:</p>\r\n\r\n<p> </p>\r\n\r\n<ul>\r\n	<li>Every item was 100% handmade by Heroverse artists.  The finished product may differ somewhat from the original images. We hope you understand any reasonable differences</li>\r\n	<li>Easy-clean surface (simply use a damp cloth to wipe)</li>\r\n	<li>Custom orders are welcome. Please share your design with us so that we can customize it for you.</li>\r\n</ul>', 'wrist-rests', NULL, '2025-12-16', '2025-12-16'),
('black-yin-yang-resin-wrist-rest', 'Black Yin Yang Resin Wrist Rest', 'Best Product', 115, 150, 'Publish', 'https://heroverseart.sgp1.cdn.digitaloceanspaces.com/assets/images/2T618zVu_black-and-white-koi-resin-wrist-rest-1.jpg.jpg', 'wrist rest keycap, Wrist Rest Pad, handmade palm rest, resin wrist rest, Wood wrist rest, Brown wrist rest, custom wrist rest, pc masterrace, Yin Yang Wrist rest, Black wrist rest, Heroverse wrist rest, wrist rest resin, Gaming wrist rest', '<p>The Most Stylish &amp; Comfortable Wrist Rest You’ve Ever Seen</p>\r\n\r\n<p> </p>\r\n\r\n<p>In Chinese culture, Yin and Yang represent the two most basic principles of the universe. While the Yin represents the negative or feminine nature, the yang stands for the positive or masculine side. But, despite their differences, life cannot exist without one of these forces.</p>\r\n\r\n<p><img alt=\"Black and white koi fish resin wrist rest\" src=\"https://i0.wp.com/hirosarts.com/wp-content/uploads/2022/05/black-and-white-koi-resin-wrist-rest-2.jpg.jpg?resize=644%2C515&amp;ssl=1\"></p>\r\n\r\n<p>Black yin yang resin wrist rest</p>\r\n\r\n<p>In the form of Koi fish, our Black and White resin wrist rest create the same energy as Yin and Yang. Bring this stunning Black Yin Yang resin wrist rest to your desk to increase your personal flow of cosmos energy. Using this wonderful black Koi pad keyboard support cushion not only creates a comfortable feel when using your PC but also generates a beautiful harmony in your thoughts, your home, and your surroundings.</p>\r\n\r\n<p><img alt=\"Black yin yang resin wrist rest\" src=\"https://i0.wp.com/hirosarts.com/wp-content/uploads/2022/05/black-and-white-koi-resin-wrist-rest-6.jpg.jpg?resize=644%2C805&amp;ssl=1\"></p>\r\n\r\n<p>Black yin yang resin wrist rest</p>\r\n\r\n<p>Even better, thanks to the high-quality resin, our Black Yin Yang Resin Wrist Rest can be very durable and also comes at a more affordable price. Plus, it also gives the<a href=\"https://heroverseart.com/catalog?category=wrist-rests\"> </a><a href=\"https://heroverseart.com/catalog?category=wrist-rests\">wrist rest</a> a certain brightness to glow beautifully under the light.</p>\r\n\r\n<p>Tech Specs:</p>\r\n\r\n<p> </p>\r\n\r\n<ul>\r\n	<li>Size 60%: 30 x 1.5 x 2 (the thinnest place is 1.5 cm)</li>\r\n	<li>Size TKL: 36 x 1.5 x 2 (the thinnest place is 1.5 cm)</li>\r\n	<li>Full size: 44 x 1.5 x 2 (the thinnest place is 1.5 cm)</li>\r\n	<li>Material: Resin epoxy</li>\r\n	<li>Smooth, solvent-resistant polish for surface protection</li>\r\n</ul>\r\n\r\n<p>Inside the package:</p>\r\n\r\n<p> </p>\r\n\r\n<ul>\r\n	<li>1 Black Yin Yang Resin Wrist Rest</li>\r\n	<li>1 card</li>\r\n</ul>\r\n\r\n<p>Sidenote:</p>\r\n\r\n<p> </p>\r\n\r\n<ul>\r\n	<li>Only use a damp and soft cloth to clean the surface.</li>\r\n	<li>Please keep this product away from high heat and water.</li>\r\n	<li>100% handmade by experienced artists. So the product you receive may be slightly different from the image in texture or color.</li>\r\n</ul>', 'wrist-rests', NULL, '2025-05-20', '2025-05-20'),
('blastoise-pokemon-keycap', 'Blastoise Pokemon Keycap', NULL, 29.5, 42.99, 'Publish', 'https://heroverseart.sgp1.cdn.digitaloceanspaces.com/assets/images/uQwwps0l_Blastoise-pokemon-keycap-2-e1705129034724.jpg', 'pokemon key cap, Pokemon keycap, pokemon custom, pokemon gifts, pokemon collecter, keycap artisan, esc keycap, custom resin keycap, gift for friends, gift for boyfriend, custom pokemon, artisan keycap, blastoise keycaps', '<p>The Blastoise Pokemon keycap was created by a Vietnamese resin artist - Inspired by the famous cartoon Pokemon.</p>\r\n\r\n<p>It is a perfect gift for Pokemon fans. This stunning keycap will be a spotlight on your keyboard!</p>\r\n\r\n<p>The process of making an artisan keycap is complicated, but we enjoy it…. We always produce the keycap characters by casting them through shaped molds. We do not have them easily printed in 3D and just like that, the keycap details come straight out of a machine.</p>\r\n\r\n<p>Everything is done by the hands of our artisans, preparing the molds, pouring resin, and coloring the details. Ultimately, this painting step is hands down one of the hardest things we faced during the production of Heroverse. Molds in the collection are very small, so it’s very challenging to paint the details and keep them spirited as much as possible. We had to apply 3 - 5 layers of paint for each keycap so the colors can have a certain thickness and be clearer to our eyes.</p>\r\n\r\n<p>We hope you can wait patiently to receive our keycaps! Made from durable resin hand-painted in eye-popping colors by our artisans, each little toad is painted by hand to ensure it lives up to our high standards. This will obviously add some more inspiration to your work corner and keep you more creative to do what you love and love what you do.</p>\r\n\r\n<p> </p>\r\n\r\n<p>INCLUDED: Keycap only, Not include Keyboard</p>\r\n\r\n<p>- This product is handmade, every keycap that you receive will a little bit different such as: the texture, the color...<br>\r\n- For long time use, please keep this product away from heat and water. Don\'t soak it into the water. Wet tissue is acceptable</p>', 'keycaps', 'pokemon-keycaps', '2025-12-16', '2025-12-16'),
('blue-river-resin-wood-ashtray', 'Blue River Resin Wood Ashtray', 'Top Product', 75, 97.5, 'Publish', 'https://heroverseart.sgp1.cdn.digitaloceanspaces.com/assets/images/I6OlJnD5_blue-river-resin-wood-ashtray-4.jpg', 'Ashtray Resin Epoxy, Ashtray resin wood, tobacciana epoxy, cigar case wood, vintage decor home, gifts for men, housewarming gift, birthday gift wood, anniversary gift, ashtray resin, rolling tray, ashtray cigar, custom ashtray resin', '<p>Elevate your smoking experience with this exquisite handmade cigar ashtray. Crafted from premium wood and infused with vibrant epoxy resin, this unique piece offers both style and functionality.</p>\r\n\r\n<p>This is a natural product. Just as in nature, every tree is different and every slab is different. There are many variations of walnut, wood grain and coloring will be different on each and every ashtray.</p>\r\n\r\n<p>Tech specs:</p>\r\n\r\n<ul>\r\n	<li>Size S: 28x14.5x2.4cm</li>\r\n	<li>Size M: 19x14.5x2.4cm</li>\r\n	<li>0.5 inches in error</li>\r\n</ul>', 'resin-trays', NULL, '2025-05-20', '2025-05-20'),
('broken-gundam-in-deep-ocean-epoxy-lamp', 'Broken Gundam In Deep Ocean Epoxy Lamp', 'Flash Deal', 59.5, 129, 'Publish', 'https://heroverseart.sgp1.cdn.digitaloceanspaces.com/assets/images/xbb8DDQ6_BROKEN-gundam-in-deep-ocean-epoxy-lamp-15.jpg', 'epoxy lamp, epoxy resin lamp, desk lamp, custom lamp, handmade gift, resin night light, resin lamp, unique lamp, custom night light, art deco lamp, personalized gift, home decor, gift for him', '<p><strong>Decorate your room with BROKEN Gundam in Deep Ocean Epoxy Lamp</strong></p>\r\n\r\n<p>Are you ready to embark on an enchanting underwater adventure? Brace yourselves for the arrival of the <strong>BROKEN Gundam in Deep Ocean Epoxy Lamp. </strong>The serene depths of the ocean and the ruins of a fallen Gundam come together in perfect harmony with the delicate hands of our artisans.</p>\r\n\r\n<p>The epoxy lamp\'s main attraction is a moss-covered rock with a statue of Gundam seated on it. The mighty Gundam finds refuge from its handicap after a fierce fight in the fascinating sea.</p>\r\n\r\n<p>Aside from the figure, the multi-colored LEDs make BROKEN Gundam in Deep Ocean Resin Lamp so vivid. Each color will offer you a different picturesque scene of the mysterious ocean highlighted by the great machine.</p>\r\n\r\n<p>Turn your space into a mysterious world with the <strong>BROKEN Gundam in Deep Ocean Resin Night Light. </strong>If you want to see more stunning themes, you should visit the collection of <a href=\"https://heroverseart.com/catalog?category=epoxy-lamps\">epoxy lamps</a>.</p>\r\n\r\n<p><strong>Tech specs:</strong></p>\r\n\r\n<ul>\r\n	<li>Size M: 2.4\"x3.5\"x2.4\"</li>\r\n	<li>Size L: 2.8\"x4.7\"x2.8\"</li>\r\n</ul>\r\n\r\n<p><strong>Inside the package:</strong></p>\r\n\r\n<ul>\r\n	<li>Handmade Night Light</li>\r\n	<li>USB cable for the light stand</li>\r\n	<li>RGB LED 16 colors</li>\r\n	<li>Remote control without battery</li>\r\n</ul>', 'resin-lamps', 'anime-lamps', '2025-05-15', '2025-05-15'),
('bulbasaur-artisan-keycap', 'Bulbasaur Artisan Keycap', 'Best Product', 29.5, 42.99, 'Publish', 'https://heroverseart.sgp1.cdn.digitaloceanspaces.com/assets/images/bONQoniE_Bulbasaur-artisan-keycap-4.jpg', 'Bulbasaur Keycap, Pokemon Keycap, artisan keycap, blue keycaps, cherry mx keycaps, gmk keycaps, green keycaps, kawaii keycaps, keycaps custom, keycaps set backlit, korean keycaps, pokemon anime, xda keycaps', '<p>Heroverse has been devoted to producing high-quality resin keycaps, Bulbasaur artisan keycaps are one of them. Anyone who is a fan of Pokemon has to have something with Bulbasaur on it, and this Bulbasaur artisan keycap is no exception. If you are a collector of Pokemon keycaps you definitely want to add this to your collection.</p>\r\n\r\n<p><strong>Perfect Gift for Bulbasaur Lover</strong></p>\r\n\r\n<p>Each Bulbasaur artisan keycap is made in a process that closely replicates the original Pokémon character. Bulbasaur is a Grass/Poison-type Pokémon and the first of the original Kanto starter Pokémon. Bulbasaur can be found in grasslands and forests throughout the Kanto region. </p>\r\n\r\n<p>The quadrupedal Pokémon with blue-green skin and red eyes is very calm and tends to keep to themselves, but they will fiercely fight off anyone who picks on it or any member of its species. Pokemon Bulbasaur resin keycap It\'s a perfect gift for any fan of Pokemon games or movies.</p>\r\n\r\n<p><strong>Gorgeous Bulbasaur resin keycap at the most reasonable price</strong></p>\r\n\r\n<p>This Bulbasaur handmade keycap is unique for its astonishing color and craftsmanship. It is hand-cast, hand-painted, and assembled by Heroverse. Heroversean Asia based designer and manufacturer of collectible resin art, has been devoted to producing high-quality resin keycaps with a  variety of designs such as bunny artisan keycaps, astronaut keycaps.</p>\r\n\r\n<p> </p>\r\n\r\n<p><em>There may be small surface scratches and other minor flaws. Please consider this before purchasing. We hope you can enjoy it as a unique product. </em></p>\r\n\r\n<p>Because of its popularity, some people may be attracted by its lower price while others may be tempted by its higher price. We advise you to buy Pokemon Bulbasaur Artisan Keycap from us because we offer the most reasonable prices and the highest quality among similar products. Here you can get the most suitable product at the most reasonable price!</p>\r\n\r\n<p>Get a unique Pokemon Bulbasaur artisan keycap while not breaking your budget.</p>\r\n\r\n<p>Follow us on <em><strong>Instagram </strong></em>or <em><strong>Behance </strong></em>for more information</p>', 'keycaps', 'pokemon-keycaps', '2025-12-16', '2025-12-16'),
('bulbasaur-pokemon-keyboard-knob', 'Bulbasaur Pokémon Keyboard Knob', 'Best Product', 34.99, 0, 'Publish', 'https://heroverseart.sgp1.cdn.digitaloceanspaces.com/assets/images/uYGfrOg3_Bulbasaur-Pokemon-Keyboard-Knob-3.jpg', 'Bulbasaur Keycap, Bulbasaur pokemon, Fushigidane Keycap, Pokemon Keycap, R1 keycap, SA profile keycap, artisan keycap, bulbasaur planter, custom keycaps, keycaps custom, pokemon anime, pokemon art', '<p>The Bulbasaur Pokémon Keyboard Knob: A Standout Addition To Your Mechanical Keyboard</p>\r\n\r\n<p> </p>\r\n\r\n<p>Upgrade your mechanical keyboard with the unique, handcrafted Bulbasaur Pokémon Keyboard Knob. Carefully crafted with attention to detail, this knob adds a personal touch to your setup while ensuring a comfortable typing experience. The vibrant colors and intricate design make it a must-have for any Pokémon fan.</p>\r\n\r\n<p>Made from high-quality resin, this Bulbasaur knob is built to last, handling heavy use without losing its appeal. Its ergonomic design offers smooth, responsive keypresses, boosting both your productivity and gaming performance.</p>\r\n\r\n<p><img alt=\"Bulbasaur pokémon keyboard knob\" src=\"https://i0.wp.com/hirosarts.com/wp-content/uploads/2024/08/Bulbasaur-Pokemon-Keyboard-Knob-1.jpg?resize=500%2C500&amp;ssl=1\"></p>\r\n\r\n<p>Bulbasaur pokémon keyboard knob</p>\r\n\r\n<p>Explore more of <a href=\"https://heroverseart.com/catalog?category=keyboard-knobs\">Heroverse\'s artisan keyboard knobs</a> and give your keyboard a personalized touch.</p>\r\n\r\n<p>Tech Specs:</p>\r\n\r\n<p> </p>\r\n\r\n<ul>\r\n	<li>Switch type: Compatible with Cherry MX switches &amp; clones</li>\r\n	<li>Material: Resin</li>\r\n	<li>Backlit &amp; UV light support (Weak)</li>\r\n	<li>Design and Handcrafted by Heroverse</li>\r\n</ul>\r\n\r\n<p>Inside the package:</p>\r\n\r\n<p> </p>\r\n\r\n<ul>\r\n	<li>1 keycap by Heroverse</li>\r\n	<li>1 thank you card</li>\r\n	<li>2 rubber finger gloves</li>\r\n</ul>\r\n\r\n<p>Sidenote:</p>\r\n\r\n<p> </p>\r\n\r\n<ul>\r\n	<li>Every product was 100% handmade.</li>\r\n	<li>The final product may vary slightly from the original photos. We would love to ask you to tolerate any reasonable differences.</li>\r\n	<li>For a long time use, please keep this product away from heat and water. Simply use a damped tissue to clean the surface.</li>\r\n</ul>', 'keyboard-knobs', NULL, '2025-12-16', '2025-12-16'),
('charizard-pokemon-artisan-keycap', 'Charizard Pokemon Artisan Keycap', NULL, 29.5, 42.99, 'Publish', 'https://heroverseart.sgp1.cdn.digitaloceanspaces.com/assets/images/KbHVeDij_charizard-pokemon-keycap-1.jpg', 'pokemon keycap, custom pokemon gift, artisan keycaps, resin keycaps, custom gift, birthday gift, mechanical keyboard, gift for her, gift for him, keycap custom, resin keycap, cute keycap, Charizard keycap', '<p>Level up your Pokémon collection with Charizard Pokemon Artisan Keycap</p>\r\n\r\n<p><strong>Custom Charizard Pokemon Artisan Keycaps</strong> have been well-known as a collector hobby and even an art form due to their uniqueness and artistry. The Pokemon <strong>artisan keycap</strong> perfectly captures the Pokemon of your dream and presents it in the space of a single key.</p>\r\n\r\n<p>These<strong> handmade Charizard resin keycaps </strong>feature fiery volcanic settings with the Charizard pokemon standing in the middle. This cool ESC key is ready to stand guard on your keyboard to keep you safe from the wilds of the internet.</p>\r\n\r\n<p>This novelty keycap is available in 2 sizes which are 1u (ECS) and 1.5u so that you can choose the best fit for your keyboard. So don’t hesitate to check other pokemon artisan keycaps out on our website!</p>\r\n\r\n<p><strong>Tech specs:</strong></p>\r\n\r\n<ul>\r\n	<li>Material: Resin epoxy</li>\r\n	<li>Switch type: Compatible with Cherry MX switches &amp; clones</li>\r\n	<li>Profile keycap: SA</li>\r\n	<li>Profile row: R1</li>\r\n	<li>Height: 16 mm </li>\r\n	<li>Custom any color</li>\r\n	<li>Backlit &amp; UV light support (weak)</li>\r\n	<li>Design and Handcrafted by Heroverse</li>\r\n</ul>\r\n\r\n<p><strong>Inside the package:</strong></p>\r\n\r\n<ul>\r\n	<li>1 resin artisan keycap by Heroverse</li>\r\n	<li>1 card</li>\r\n	<li>2 rubber finger gloves</li>\r\n</ul>\r\n\r\n<p><strong>Sidenote:</strong></p>\r\n\r\n<ul>\r\n	<li>Every product was 100% handmade. The final product may differ slightly from the original photos. We would love to ask you to tolerate any reasonable differences.</li>\r\n	<li>For a long time use, please keep this product away from heat and water. Don\'t soak it into the water. Wet tissue is acceptable.</li>\r\n</ul>', 'keycaps', 'pokemon-keycaps', '2025-12-16', '2025-12-16'),
('charmander-pokemon-keycap', 'Charmander Pokemon Keycap', 'Flash Deal', 29.5, 0, 'Publish', 'https://heroverseart.sgp1.cdn.digitaloceanspaces.com/assets/images/83LLpg5z_charmander-keycap-7.jpg-e1698117525795.jpg', 'Charmander Pokemon, Charmander keycap, Charmander custom, pokemon keycap, esc keycap, custom resin keycap, Charmander resin, dykeycap, Cherry MX keycap, keycaps, gift ideas, gift for boyfriend', '<p>Add a fiery touch to your keyboard with Charmander Pokemon keycap</p>\r\n\r\n<p>Introducing the Charmander Pokemon Keycap - the ultimate accessory for any Pokemon fan\'s keyboard! This keycap is not only a functional addition to your keyboard, but also a fun and playful way to express your love for the popular game and anime series.</p>\r\n\r\n<p>As a beloved character from the Pokemon franchise, Charmander has captured the hearts of fans worldwide with his cute appearance and fierce battle skills. Now, you can bring a piece of that magic to your own keyboard with this charming keycap.</p>\r\n\r\n<p>Whether you\'re battling it out in the Pokemon games or watching the anime series, this keycap is the perfect way to show off your love for all things Pokemon. The high-quality construction ensures that it will withstand the rigors of daily use, while the colorful and detailed design will add a touch of fun and whimsy to your keyboard.</p>\r\n\r\n<p>So why settle for a boring old keycap when you can have a Charmander Pokemon Keycap? Get yours today and add a touch of Pokemon magic to your keyboard!</p>\r\n\r\n<p><strong>Tech Specs:</strong></p>\r\n\r\n<ul>\r\n	<li>Switch type: Compatible with Cherry MX switches &amp; clones</li>\r\n	<li>Material: Resin</li>\r\n	<li>Profile: SA profile</li>\r\n	<li>Size: 1u</li>\r\n	<li>Backlit &amp; UV light support (Weak)</li>\r\n	<li>Design and Handcrafted by Heroverse</li>\r\n</ul>\r\n\r\n<p><strong>Inside the package:</strong></p>\r\n\r\n<ul>\r\n	<li>1 keycap by Heroverse</li>\r\n	<li>1 card</li>\r\n	<li>2 rubber finger gloves</li>\r\n</ul>\r\n\r\n<p><strong>Sidenote:</strong></p>\r\n\r\n<ul>\r\n	<li>Every product was 100% handmade.</li>\r\n	<li>The final product may vary slightly from the original photos. We would love to ask you to tolerate any reasonable differences.</li>\r\n	<li>For a long time use, please keep this product away from heat and water. Simply use a damped tissue to clean the surface.</li>\r\n</ul>', 'keycaps', 'pokemon-keycaps', '2025-05-20', '2025-05-20'),
('cheese-artisan-keycap', 'Cheese Artisan Keycap', 'Top Product', 9.5, 19, 'Publish', 'https://heroverseart.sgp1.cdn.digitaloceanspaces.com/assets/images/6SvpI3sZ_cheese-keycap-2.jpg.jpg', 'custom keycap, artisan keycap, mechanical keycaps, handmade keycap, keycap cherry mx, esc keycap, resin keycap, cheese keycap, keycap', '<p>Cheese keycap: It’s snack time, bestie!</p>\r\n\r\n<p>Any cheese lover will know that if you\'ve pressed the <strong>Cheese keycap</strong>, it\'s probably snack time. It\'s the perfect punny gift for cheese enthusiasts who already have everything.</p>\r\n\r\n<p>The brilliant yellow color of this ESC Cheese artisan keycap seems to give off a scent that stimulates your taste buds.</p>\r\n\r\n<p>Indeed, is there any food on the planet that is greater than cheese? At any time of the day, it is creamy, salty, melty, gooey, fragrant, and just plain delicious.</p>\r\n\r\n<p>That’s truly what our Cheese handmade keycaps want to bring to you as well as your cheese-loving bestie.</p>\r\n\r\n<p>Along with Cheese resin keycaps, you will also find out more and more artisan keycaps at Heroverse might just be the best gift you\'ve been looking for! Check it out now!</p>\r\n\r\n<p>Tech Specs:</p>\r\n\r\n<ul>\r\n	<li>Switch type: Compatible with Cherry MX switches &amp; clones</li>\r\n	<li>Material: Resin</li>\r\n	<li>Size: 1u</li>\r\n	<li>Backlit &amp; UV light support (Weak)</li>\r\n	<li>Design and Handcrafted by Heroverse</li>\r\n</ul>\r\n\r\n<p>Inside the package:</p>\r\n\r\n<ul>\r\n	<li>1 keycap by Heroverse</li>\r\n	<li>1 card</li>\r\n	<li>2 rubber finger gloves</li>\r\n</ul>\r\n\r\n<p>Sidenote:</p>\r\n\r\n<ul>\r\n	<li>Every product was 100% handmade.</li>\r\n	<li>The final product may vary slightly from the original photos. We would love to ask you to tolerate any reasonable differences.</li>\r\n	<li>For a long time use, please keep this product away from heat and water. Simply use a damped tissue to clean the surface.</li>\r\n</ul>', 'keycaps', 'cute-keycaps', '2025-12-16', '2025-12-16'),
('clear-resin-and-wood-wrist-rest', 'Clear Resin And Wood Wrist Rest', 'Best Product', 59, 100, 'Publish', 'https://heroverseart.sgp1.cdn.digitaloceanspaces.com/assets/images/8ZXF41n2_translucent-wrist-rest.jpg-e1649473477308.jpg', 'artisan keycap, gift, Custom keycap, Keycap Artisan, keyboard, Keycap Resin, Wood Wrist Rest, Handmade Writst Rest, wrist rests, Resin and Wood, Resin Wrist Rest, Handmade Wrist rest, discount', '<p>keyboard wrist rest comes in all sizes for all types of keyboards.</p>\r\n\r\n<p> </p>\r\n\r\n<p>Specs:</p>\r\n\r\n<p> </p>\r\n\r\n<ul>\r\n	<li>Size 60%: 30 x 1,5 x 2 (the thinnest place is 1.5 cm)</li>\r\n	<li>Size 65%: 32 x 1,5 x 2 (the thinnest place is 1.5 cm)</li>\r\n	<li>Size TKL: 36 x 1,5 x 2 (the thinnest place is 1.5 cm)</li>\r\n	<li>Full size: 44 x 1,5 x 2 (the thinnest place is 1.5 cm)</li>\r\n	<li>And we can make any custom size if you want.</li>\r\n	<li>Material: Wood and resin</li>\r\n	<li>Smooth, solvent-resistant polish for surface protection</li>\r\n</ul>\r\n\r\n<p>Inside the package:</p>\r\n\r\n<p> </p>\r\n\r\n<ul>\r\n	<li>1 wrist rest by Heroverse</li>\r\n	<li>1 card</li>\r\n</ul>\r\n\r\n<p>Sidenote:</p>\r\n\r\n<p> </p>\r\n\r\n<ul>\r\n	<li>Every product was 100% handmade. The final product may vary slightly from the original photos. We would love to ask you to tolerate any reasonable differences.</li>\r\n	<li>Easy-clean surface (simply use a damp cloth to wipe)</li>\r\n</ul>', 'wrist-rests', NULL, '2025-05-20', '2025-05-20'),
('colorful-resin-and-wood-wrist-rest', 'Colorful Resin And Wood Wrist Rest', 'Undefine Product', 64.99, 91.65, 'Publish', 'https://heroverseart.sgp1.cdn.digitaloceanspaces.com/assets/images/KmExTxDK_colorful-resin-wrist-rest-1-e1689324003614.jpg', 'keyboard wrist rest, wrist rest keycap, resin wrist rest, stone wrist rest, artisan wrist rest, marble wrist rest, wrist rest keyboard, mouse wrist rest, tkl wrist rest, cute wrist rest, wooden wrist rest, wrist rest resin, wrist rest epoxy', '<p>More than just ergonomic support, our resin and wood wrist rest are portable pieces of oil paint that add a dash of style to any tabletop.</p>\r\n\r\n<p>The wrist rests are designed in the East Asian style of ink wash brush painting. Our artisans had to sharpen the wood carefully, and then paint multi-layers to create greater hue effects and a more intense feeling of thickness. The result is an earthy, multi-colored pattern—a combo that will complement virtually any keyboard. Done in a live-edge style, the wood fibers are visible through the resin, as if looking at a bug petrified in amber.</p>\r\n\r\n<p><img alt=\"Green wrist rest\" src=\"https://i0.wp.com/hirosarts.com/wp-content/uploads/2021/08/green-wrist-rest-1.jpg?resize=300%2C254&amp;ssl=1\"></p>\r\n\r\n<p>The wrist rest is visually aesthetic and allows you to glide effortlessly across the smooth surface while typing. The resin and wood wrist rest includes a polishing cloth and four rubber bump-ons to keep it from sliding on your desktop.</p>\r\n\r\n<p>We have 4 size:<br>\r\nSize 60% : 30 x 1,5 x 2 (the thinnest place is 1.5 cm)<br>\r\nSize 65% : 32 x 1,5 x 2 (the thinnest place is 1.5 cm)<br>\r\nSize TKL : 36 x 1,5 x 2 (the thinnest place is 1.5 cm)<br>\r\nSize Full size : 44 x 1,5 x 2 (the thinnest place is 1.5 cm)<br>\r\nAnd we can make any custom size if you want.<br>\r\nMaterial: Wood and resin<br>\r\nSmooth, solvent-resistant polish for surface protection<br>\r\nEasy-clean surface (simply use damp cloth to wipe)</p>\r\n\r\n<p>Kindly share with us your design, we can customize that for you.</p>\r\n\r\n<p>Handmade in Vietnam</p>\r\n\r\n<p>Ready to ship worldwide</p>\r\n\r\n<p>Thank you and happy shopping!</p>', 'wrist-rests', NULL, '2025-05-20', '2025-05-20'),
('custom-anime-keyboard-wrist-rest', 'Custom Anime Keyboard Wrist Rest', 'New Arrival', 68.99, 89.99, 'Publish', 'https://heroverseart.sgp1.cdn.digitaloceanspaces.com/assets/images/rsIvWTej_IMG_9312-copy.jpg.jpg', 'rug, custom, carpet, gaming, area rug, custom rug, anime, keyboard, computer, office, cartoon, keyboard wrist rest, keyboard rug', '<p>Step into a world of anime enchantment with Custom Anime Keyboard Wrist Rest</p>\r\n\r\n<p> </p>\r\n\r\n<p>Let your beloved characters accompany you on your gaming adventures and infuse your setup with the essence of your favorite anime series.</p>\r\n\r\n<p>Experience the excitement right from the beginning as you rest your wrists on this specially designed keyboard accessory. With a custom design featuring iconic anime characters, your wrist rest becomes a personalized expression of your anime fandom.</p>\r\n\r\n<p><img alt=\"Custom anime keyboard wrist rest\" src=\"https://i0.wp.com/hirosarts.com/wp-content/uploads/2023/05/IMG_9311-copy.jpg.jpg?resize=600%2C600&amp;ssl=1\"></p>\r\n\r\n<p>Custom anime keyboard wrist rest</p>\r\n\r\n<p>Indulge in the ergonomic comfort of the Custom Anime Keyboard Wrist Rest, providing optimal support during those intense gaming sessions. Let your chosen anime characters inspire you, bringing their unique traits and powers to your fingertips as you immerse yourself in the virtual world.</p>\r\n\r\n<p>Don\'t miss the chance to own the Custom Anime Keyboard Wrist Rest. Click now to unlock the anime magic and elevate your gaming setup to new heights. Embrace your passion for anime and click below to make it yours today.</p>\r\n\r\n<p>Specs:</p>\r\n\r\n<p> </p>\r\n\r\n<ul>\r\n	<li>60%: 300mm x 80mm</li>\r\n	<li>65%: 320mm x 80mm</li>\r\n	<li>TKL: 360mmx80mm</li>\r\n	<li>Fullsize: 440mmx80mm</li>\r\n	<li>And we can make any custom size if you want.</li>\r\n	<li>Material: Wood and resin</li>\r\n	<li>Smooth, solvent-resistant polish for surface protection</li>\r\n</ul>\r\n\r\n<p>Inside the package:</p>\r\n\r\n<p> </p>\r\n\r\n<ul>\r\n	<li>1 wrist rest by Heroverse</li>\r\n	<li>1 card</li>\r\n</ul>\r\n\r\n<p>Sidenote:</p>\r\n\r\n<p> </p>\r\n\r\n<ul>\r\n	<li>Every product was 100% handmade. The final product may vary slightly from the original photos. We would love to ask you to tolerate any reasonable differences.</li>\r\n	<li>Easy-clean surface (simply use a damp cloth to wipe)</li>\r\n</ul>', 'wrist-rests', NULL, '2025-12-16', '2025-12-16'),
('custom-dry-flower-artisan-keycap', 'Custom Dry Flower Artisan Keycap', 'Flash Deal', 9.99, 0, 'Publish', 'https://heroverseart.sgp1.cdn.digitaloceanspaces.com/assets/images/E4D0XhH9_dry-flower-artisan-keycap-15.jpg', 'artisan keycap, esc keycap, handmade keycap, resin keycap, keycap set, backlit keycap, keycaps set backlit, custom keycap, flower keycap, sakura keycap, dry flower keycap, combo keycap, keycap resin', '<p>Backlit dry flower artisan keycaps: Unique gifts for her</p>\r\n\r\n<p>These dry flower artisan keycaps are made from clear resin and feature light pink dried flowers with gold flakes. The meticulous hands of our artisans got involved in every stage of the production process from the tiniest detail: preparing the molds, pouring resin, and coloring the details.</p>\r\n\r\n<p>It took us several days and a lot of attention to detail to complete each flower keycap so that the products you receive are flawless and one-of-a-kind. These cheap artisan keycaps are a budget yet awesome way to personalize your mechanical keyboard. </p>\r\n\r\n<p>These see-through keycaps are also available in sets of ESC and Shift, ESC, Shift, and Spacebar, and even a set of 7 keycaps (ESC, Alt/Ctrl, Tab, Capslock, Backspace, Spacebar, Enter/Left Shift, arrow keycaps). The more keycaps you buy, the more money you save: 10% off for a set of 2-3 products and 15% off for a set of 7 products.</p>\r\n\r\n<p>Minimalist yet graceful, this cream-colored keycap is for those who want to elevate the style of their keyboard.  add a touch of elegance to the monotonous mechanical keyboard or in case you are looking for a gift idea for your friends or your family.</p>\r\n\r\n<p><strong>Tech specs:</strong></p>\r\n\r\n<ul>\r\n	<li>Material: Resin epoxy</li>\r\n	<li>Switch type: Compatible with Cherry MX switches &amp; clones</li>\r\n	<li>Profile keycap: OEM</li>\r\n	<li>Height: 12mm</li>\r\n	<li>Color: pink and white keycaps/white and pink keycaps/light pink keycaps/pastel pink keycaps (Custom color option is available)</li>\r\n	<li>Backlit &amp; UV light support</li>\r\n	<li>Design and Handcrafted by Heroverse</li>\r\n</ul>\r\n\r\n<p><strong>Inside the package:</strong></p>\r\n\r\n<ul>\r\n	<li>A <strong>dry flower artisan keycap</strong> by Heroverse</li>\r\n	<li>1 card</li>\r\n	<li>2 rubber finger gloves</li>\r\n</ul>\r\n\r\n<p><strong>Sidenote:</strong></p>\r\n\r\n<ul>\r\n	<li>Every product was 100% handmade. The final product may differ slightly from the original photos. We would love to ask you to tolerate any reasonable differences.</li>\r\n	<li>For a long time use, please keep this product away from heat and water. Don\'t soak it into the water. Wet tissue is acceptable.</li>\r\n</ul>', 'keycaps', 'cute-keycaps', '2025-12-16', '2025-12-16'),
('custom-hollow-knight-keycap', 'Custom Hollow Knight Keycap', 'New Arrival', 29.5, 36.99, 'Publish', 'https://heroverseart.sgp1.cdn.digitaloceanspaces.com/assets/images/QkdTvY3g_keycap-4.JPG.jpg', 'birthday gift, keycap, 1u keycap, artisan keycap, epoxy resin keycap, anime keycap, custom keycap, Hollow Knight Keycap, Hollow Knight, cute keycap, knight and hornet, hornet, halloween gift', '<p>Say hello to your new knight in shining armor - Hollow Knight!</p>\r\n\r\n<p>With his signature charm and fierce determination, this custom keycap will make all your gaming and typing adventures more exciting than ever before. Imagine the satisfaction of hitting that \"Enter\" key with the power of the Hollow Knight behind it - it\'s like the ultimate victory in a boss battle.</p>\r\n\r\n<p>Not only is this keycap functional, but it also adds some serious style points to your keyboard. The intricate design and attention to detail will make all your fellow gamers and Hollow Knight fans jealous.</p>\r\n\r\n<p>So, what are you waiting for? Upgrade your keyboard and show off your love for Hollow Knight with this custom keycap. Your fingers (and your gaming skills) will thank you.</p>\r\n\r\n<p>Tech Specs:</p>\r\n\r\n<ul>\r\n	<li>Switch type: Compatible with Cherry MX switches &amp; clones</li>\r\n	<li>Material: Resin</li>\r\n	<li>Design and Handcrafted by Heroverse</li>\r\n</ul>\r\n\r\n<p>Inside the package:</p>\r\n\r\n<ul>\r\n	<li>1 keycap by Heroverse</li>\r\n	<li>1 card</li>\r\n	<li>2 rubber finger gloves</li>\r\n</ul>\r\n\r\n<p>Sidenote:</p>\r\n\r\n<ul>\r\n	<li>Every product was 100% handmade.</li>\r\n	<li>The final product may vary slightly from the original photos. We would love to ask you to tolerate any reasonable differences.</li>\r\n	<li>For a long time use, please keep this product away from heat and water. Simply use a damped tissue to clean the surface.</li>\r\n</ul>', 'keycaps', 'anime-keycaps', '2025-12-16', '2025-12-16'),
('custom-jellyfish-artisan-keycap', 'Custom Jellyfish Artisan Keycap', 'Flash Deal', 29.5, 39.99, 'Publish', 'https://heroverseart.sgp1.cdn.digitaloceanspaces.com/assets/images/kfa80z7J_Jellyfish-artisan-keycap-11-e1649386269154.jpg', 'artisan keycap, gift, Custom keycap, Keycap Artisan, keyboard, Keycap Resin, Koi fish keycap, keycap anime, koi keycap, jellyfish keycap, handmade keycap', '<p>Jellyfish artisan keycap - A mannerist piece of art</p>\r\n\r\n<p>More than a keycap, this <strong>Jellyfish artisan keycap</strong> is a mannerist piece of art. These jellyfish keycaps are made of clear resin and feature a miniature jellyfish surrounded by its own gorgeous habitat.</p>\r\n\r\n<p>It takes us several days to complete each resin artisan keycap. In the production process including preparing the molds, pouring resin, and coloring the details…, the painting stage is hands down the most difficult thing due to the tiny size and the intricate design of jellyfish molds. But with all the dedication and craft, our artisans created flawless and well-guided to-the-design keycaps.</p>\r\n\r\n<p>These <strong>SA and OEM</strong> <strong>profile resin artisan keycaps </strong>are available in a wide range of colors so that you can pick up your favorite one to beautify your keyboard.</p>\r\n\r\n<p>If you are looking for a gift idea for your friend, your family, or a gorgeous decor piece for your mechanical keyboard, our custom painted keycaps are perfect options due to their elegance and artistry.</p>\r\n\r\n<p><strong>Tech specs:</strong></p>\r\n\r\n<ul>\r\n	<li>Material: Resin epoxy</li>\r\n	<li>Switch type: Compatible with Cherry MX switches &amp; clones</li>\r\n	<li>Profile keycap: SA OEM</li>\r\n	<li>Profile row: ESC</li>\r\n	<li>Height: 16 mm (SA), 12mm (OEM)</li>\r\n	<li>Custom any color (pink and black keycap or any color combination you desire)</li>\r\n	<li>Design and Handcrafted by Heroverse</li>\r\n</ul>\r\n\r\n<p><strong>Inside the package:</strong></p>\r\n\r\n<ul>\r\n	<li>1 Custom Jellyfish artisan keycap by Heroverse</li>\r\n	<li>1 card</li>\r\n	<li>2 rubber finger gloves</li>\r\n</ul>\r\n\r\n<p><strong>Sidenote:</strong></p>\r\n\r\n<ul>\r\n	<li>Every product was 100% handmade. The final product may vary slightly from the original photos. We would love to ask you to tolerate any reasonable differences.</li>\r\n	<li>For a long time use, please keep this product away from heat and water. Don\'t soak it into the water. Wet tissue is acceptable.</li>\r\n</ul>', 'keycaps', 'cute-keycaps', '2025-12-16', '2025-12-16'),
('cute-cat-keycaps', 'Cute Cat Keycaps', 'Flash Deal', 7.5, 15, 'Publish', 'https://heroverseart.sgp1.cdn.digitaloceanspaces.com/assets/images/GYFPXpIX_cute-cat-keycaps13.jpg.jpg', 'Black cat keycap,Cat Keycap,Kitty keycap,Yellow cat keycap,anime keycap,custom keyboard,custom keycap,cute cat keycap,cat gifts,gift for her,cat decor,cat keycaps,cute keycaps', '<p>Cute Cat keycaps: Sparkling eyes are watching you!</p>\n\n<p>Any of us would like to have these purring, pooping, meowing pets beside us. With that in mind, we created these heart-stolen <strong>cute cat keycaps</strong>, and we bet you will fall in love with them.</p>\n\n<p> </p>\n\n<p> </p>\n\n<p>Imagine a cat with the fluffiest fur, the most adorable, roundest black eyes, and the cutest little meowing noises to attract your focus. It is in a box, which is its favorite place to be because it makes it feel safe and secure. It will glance at you with glitter eyes as you work. How adorable!</p>\n\n<p>You can choose Cute Cat handmade keycaps from a wide variety of colors, including grey, black, yellow, white, and others. Just choose your best soulmate!</p>\n\n<p>Besides this ESC Cute Kitty artisan keycap, you might also fall in love with many other artisan keycaps at Heroverse! Check it out now!</p>\n\n<p>Tech Specs:</p>\n\n<ul>\n	<li>Switch type: Compatible with Cherry MX switches &amp; clones</li>\n	<li>Material: Resin</li>\n	<li>Size: 1u</li>\n	<li>Backlit &amp; UV light support (Weak)</li>\n	<li>Design and Handcrafted by Heroverse</li>\n</ul>\n\n<p>Inside the package:</p>\n\n<ul>\n	<li>1 keycap by Heroverse</li>\n	<li>1 card</li>\n	<li>2 rubber finger gloves</li>\n</ul>\n\n<p>Sidenote:</p>\n\n<ul>\n	<li>Every product was 100% handmade.</li>\n	<li>The final product may vary slightly from the original photos. We would love to ask you to tolerate any reasonable differences.</li>\n	<li>For a long time use, please keep this product away from heat and water. Simply use a damped tissue to clean the surface.</li>\n</ul>', 'keycaps', 'cute-keycaps', '2025-12-16', '2025-12-16'),
('cute-kirby-night-lamp', 'Cute Kirby Night Lamp', 'Undefine Product', 59, 0, 'Publish', 'https://heroverseart.sgp1.cdn.digitaloceanspaces.com/assets/images/ab5fBU2e_cute-kirby-night-lamp-3-1.jpg', 'kirby keycap, kirby plush, kirby sticker, cute keycap, baby boy gift, custom night light, resin night light, anime lamp, cute night light, anime night light, kirby emotes, kirby headphone, kirby lamp', '<ul>\r\n	<li>Size L: 2.8\"x4.7\"x2.8\"</li>\r\n</ul>\r\n\r\n<p><strong>Inside the package:</strong></p>\r\n\r\n<ul>\r\n	<li>Handmade Night Light</li>\r\n	<li>USB cable for the light stand</li>\r\n</ul>\r\n\r\n<p>\"&gt;</p>', 'resin-lamps', 'anime-lamps', '2025-05-15', '2025-05-15'),
('cyndaquil-pokemon-keyboard-knob', 'Cyndaquil Pokémon Keyboard Knob', 'Flash Deal', 34.99, 0, 'Publish', 'https://heroverseart.sgp1.cdn.digitaloceanspaces.com/assets/images/rAL10tPe_Cyndaquil-pokemon-keyboard-knob-3.jpg', 'custom pokemon, pokemon gift, fushigisou keycap, spacebar pokemon, artisan keycap, computer peripherals, esc keycap, gradient keycaps, keyboard periphelars, mechanical keycap, personalized keycap, Cyndaquil keycap, Cyndaquil', '<p>Elevate Your Setup with a Handmade Cyndaquil Pokémon Keyboard Knob</p>\r\n\r\n<p>Transform your mechanical keyboard with the unique, handmade <strong>Cyndaquil Pokémon Resin Keyboard Knob</strong>. Crafted with meticulous attention to detail, this<strong> Cyndaquil Pokémon Resin Knob</strong> not only adds a touch of personalized style to your setup but also provides a comfortable typing experience. The vibrant colors and intricate design of the Cyndaquil Pokémon Artisan Knob make it a standout piece, perfect for any Pokémon fan.</p>\r\n\r\n<p>Using high-quality resin, each <strong>Cyndaquil Pokémon Mechanical Keyboard Knob</strong> is designed to withstand heavy use while maintaining its stunning appearance. The ergonomic design ensures smooth and responsive keypresses, enhancing your overall productivity and gaming performance.</p>\r\n\r\n<p>Discover more captivating designs in our resin keyboard knob collection and bring your keyboard to life with Heroverse\'s handcrafted artisan knobs.</p>\r\n\r\n<p><strong>Tech Specs:</strong></p>\r\n\r\n<ul>\r\n	<li>Switch type: Compatible with Cherry MX switches &amp; clones</li>\r\n	<li>Material: Resin</li>\r\n	<li>Backlit &amp; UV light support (Weak)</li>\r\n	<li>Design and Handcrafted by Heroverse</li>\r\n</ul>\r\n\r\n<p><strong>Inside the package:</strong></p>\r\n\r\n<ul>\r\n	<li>1 keycap by Heroverse</li>\r\n	<li>1 thank you card</li>\r\n	<li>2 rubber finger gloves</li>\r\n</ul>\r\n\r\n<p><strong>Sidenote:</strong></p>\r\n\r\n<ul>\r\n	<li>Every product was 100% handmade.</li>\r\n	<li>The final product may vary slightly from the original photos. We would love to ask you to tolerate any reasonable differences.</li>\r\n	<li>For a long time use, please keep this product away from heat and water. Simply use a damped tissue to clean the surface.</li>\r\n</ul>', 'keyboard-knobs', NULL, '2025-05-20', '2025-05-20'),
('deep-ocean-night-light', 'Deep Ocean Night Light', 'Best Product', 54.5, 111, 'Publish', 'https://heroverseart.sgp1.cdn.digitaloceanspaces.com/assets/images/dMmSGQs3_Deep-ocean-night-light-2.jpg', 'Diver night light, resin lamp ocean, epoxy resin lamp, wood resin lamp, resin wood lamp, custom night light, kids night light, epoxy night light, Shark art, custom lamp, turtle gifts, sea turtle decor, Room decor lamp', '<p><strong>Dive into bed under with Deep Ocean Night Light</strong></p>\r\n\r\n<p>Create stunning natural scenes in a lively way with Heroverse’s <strong>Deep Ocean Night light</strong>. Both enormous animals and people are embraced by the wide and serene water.</p>\r\n\r\n<p>Our Deep Ocean resin lamp is fully handcrafted by the skillful hands of Heroverse artisans. Not only depicting the color of the deep sea but also adorning the creatures and people who are in harmony with the water, in a rhythmic and flexible way.</p>\r\n\r\n<p>Let this Deep Ocean Night light showcase your interests and give wonderful ambient lighting to make your room look (to use the lingo of the younger generation) dope!</p>\r\n\r\n<p>Heroverse also offers an amazing collection of <a href=\"https://heroverseart.com/catalog?category=epoxy-lamps\">resin wood</a> lamps. Let’s make your room to the next level now!</p>\r\n\r\n<p>Tech specs:</p>\r\n\r\n<ul>\r\n	<li>Led: 10 colors, 5W</li>\r\n	<li>Size M: 3.7x4.5\" (9.4x11.4cm)</li>\r\n	<li>Size L: 9.5x5.9\" (24.1x15cm)</li>\r\n	<li>Size XL: 10\"x8.5\" (25.4x21.6cm)</li>\r\n	<li>Color-Changing Light Bulb</li>\r\n	<li>USB cable for the light stand (USB plug with on and off button)</li>\r\n</ul>\r\n\r\n<p>Inside the package:</p>\r\n\r\n<ul>\r\n	<li>Handmade Night Light</li>\r\n	<li>USB cable for the light stand</li>\r\n	<li>Remote Control (No battery)</li>\r\n</ul>', 'resin-lamps', 'ocean-lamps', '2025-12-16', '2025-12-16'),
('devil-fruit-keycaps', 'Devil Fruit Keycaps', 'Best Product', 24.99, 34.99, 'Publish', 'https://heroverseart.sgp1.cdn.digitaloceanspaces.com/assets/images/gItQACRK_trai-ac-ma-31.jpg-e1689956320389.jpg', 'One Piece Keycap, keycap anime, devil fruit keycap, anime keycap set, Keycap Anime Keycap, Keycap One Piece, Gomu Gomu Keycap, anime Gomu Gomu, Devil Gomu Gomu, artisan keycaps, custom keycaps, cherry mx keycaps, Christmas Gift', '<p>Devil Fruit keycaps: More than simple fruits</p>\r\n\r\n<p>Devil Fruits, which at first seemed like a ridiculous way to grant characters abilities, have evolved into one of the best power ones in all of anime.</p>\r\n\r\n<p>Now all powers are gathered into <strong>Devil Fruit keycaps</strong>.</p>\r\n\r\n<p>This collection of Devil Fruit artisan keycaps comes with 9 different Devil Fruit keycaps. Each of them features its own colorways that will surely catch your eyes at the first sight.</p>\r\n\r\n<p>To achieve such excellent craftsmanship, we’ve always devoted all efforts with a passionate heart to painting every tiny layer of Devil Fruit SA Profile keycap.</p>\r\n\r\n<p>Just like a small fruit sitting on your Esc key but Devil Fruit keycap shows all of your taste and endless passion for One piece.</p>\r\n\r\n<p>Simply tell us which Devil Fruit resin keycap is in your heart, and we can make them for you. Don’t forget to check our artisan keycaps to see more anime keycaps.</p>\r\n\r\n<p>Tech Specs:</p>\r\n\r\n<ul>\r\n	<li>Switch type: Compatible with Cherry MX switches &amp; clones</li>\r\n	<li>Material: Resin</li>\r\n	<li>Profile: SA profile</li>\r\n	<li>Size: 1u</li>\r\n	<li>Backlit &amp; UV light support (Weak)</li>\r\n	<li>Design and Handcrafted by Heroverse</li>\r\n</ul>\r\n\r\n<p>Inside the package:</p>\r\n\r\n<ul>\r\n	<li>1 keycap by Heroverse</li>\r\n	<li>1 card</li>\r\n	<li>2 rubber finger gloves</li>\r\n</ul>\r\n\r\n<p>Sidenote:</p>\r\n\r\n<ul>\r\n	<li>Every product was 100% handmade.</li>\r\n	<li>The final product may vary slightly from the original photos. We would love to ask you to tolerate any reasonable differences.</li>\r\n	<li>For a long time use, please keep this product away from heat and water. Simply use a damped tissue to clean the surface.</li>\r\n</ul>', 'keycaps', 'anime-keycaps', '2025-12-16', '2025-12-16');
INSERT INTO `products` (`IdProduct`, `NameProduct`, `TypeProduct`, `NewPrice`, `OldPrice`, `StatusProduct`, `ImageURL`, `Tag`, `Description`, `Category`, `SubCategory`, `updated_at`, `created_at`) VALUES
('dragon-ball-artisan-keycap', 'Dragon Ball Artisan Keycap', 'Flash Deal', 24.9, 0, 'Publish', 'https://heroverseart.sgp1.cdn.digitaloceanspaces.com/assets/images/zO1ooWGM_dragon-ball-keycap-2.jpg', 'dragon ball z, artisan keycaps, dragon ball keycap, supper saiyan Vegeta, custom keycap, keycap resin, mechanical keycap, keycap backlit, keycap cute, dragon keycap, esc keycap, gundam keycap, anime keycap', '<p>A never-ending journey with Dragon Ball keycap</p>\r\n\r\n<p>‘Kamehameha!!!!’</p>\r\n\r\n<p>Wonder have you ever tried to mimic the Kamehameha? Even our friends, who have not read or watched Dragon Ball before, can respond immediately when they hear the word.</p>\r\n\r\n<p>The popularity of this franchise is genuinely amazing. Many people know about Goku, Gohan, and Super Saiyan. A lot of people dedicate their passion to one of the biggest fandoms in the world.</p>\r\n\r\n<p>If you have a friend who is in love with Dragon Ball, we suggest the <strong>Dragon Ball artisan keycap</strong>. The detail and vivid colors made with heart by our artisan will not let you down.</p>\r\n\r\n<p>If you are a fan of Akira Toriyama sensei, there is a high chance you will find the <strong>Dragon Ball resin keycap </strong>thrilling.</p>\r\n\r\n<p>Let\'s imagine a chibi Master Roshi keycap on your keyboard. Is it enough for you to have a Kamehameha urge?</p>\r\n\r\n<p>We once went on the journey with Piccolo and Cell. We jumped and screamed every time Goku transformed into a Super Saiyan. We got sad and happy when the series came into the final season. Somehow, for us, the story is never-ending.</p>\r\n\r\n<p>To have your journey keep going, you can choose your favorite characters to custom the <strong>Dragon Ball keycap</strong>. Moreover, we can make it in a lot of sizes, so go check the tech specs below to know what you can get.</p>\r\n\r\n<p>Check out other awesome resin keycaps like the <strong>Dragon Ball keycap </strong>here! Everything is handmade with care to make sure you will receive a one-of-a-kind gift.</p>\r\n\r\n<p>Tech Specs:</p>\r\n\r\n<ul>\r\n	<li>Switch type: Compatible with Cherry MX switches &amp; clones</li>\r\n	<li>Material: Resin</li>\r\n	<li>Profile: OEM/SA profile</li>\r\n	<li>Size: 1u, 1.25u (Alt/Ctrl), 1.5u (Tab), 1.75u (Capslock), 2u (Backspace), 2.25u (Enter/Left Shift), 2.75u (Right Shift), 6.25u (Spacebar)</li>\r\n	<li>Backlit &amp; UV light support (Weak)</li>\r\n	<li>Design and Handcrafted by Heroverse</li>\r\n</ul>\r\n\r\n<p>Inside the package:</p>\r\n\r\n<ul>\r\n	<li>1 custom image keycap by Heroverse</li>\r\n	<li>1 card</li>\r\n	<li>2 rubber finger gloves</li>\r\n</ul>\r\n\r\n<p>Sidenote:</p>\r\n\r\n<ul>\r\n	<li>Every product was 100% handmade.</li>\r\n	<li>The final product may vary slightly from the original photos. We would love to ask you to tolerate any reasonable differences.</li>\r\n	<li>For a long time use, please keep this product away from heat and water. Simply use a damped tissue to clean the surface.</li>\r\n</ul>', 'keycaps', 'anime-keycaps', '2025-12-16', '2025-12-16'),
('emilia-rezero-keycap', 'Emilia Re:zero Keycap', 'Best Product', 29.9, 39, 'Publish', 'https://heroverseart.sgp1.cdn.digitaloceanspaces.com/assets/images/3yW6HDHF_re-zero-keycap-4-1.jpg-1.jpg-min.jpg', 'rezero, re zero, Ram, Rem, Emilia, Subaru, Ferris, Felix, Beatrice, chibi, manga, anime, charm', '<p>Aspire to be a king - Emilia Re:Zero artisan keycap</p>\r\n\r\n<p>Thanks to the half-elf blood, <strong>Emilia Re:Zero resin keycap</strong> has a dreamlike, beautiful, and enchanted appearance with long silver hair and big doll eyes. Moreover, she has a truly big heart that loves and cares for people, even though she keeps claiming herself as a selfish person.</p>\r\n\r\n<p>We, who follow the Re:Zero story, cannot agree with her. Yes, Emilia is childish sometimes, but throughout the show, she always puts people before herself and we will never unrecognize that.</p>\r\n\r\n<p>So, the <strong>Emilia Re:Zero keycap</strong> is our attempt to capture her spirit. Heroverse artisan carefully put on 5-7 layers in order to bring out the liveliness of Emilia.</p>\r\n\r\n<p>This small girl who aims to be a great king one day and gives her all for it is very inspiring. We hope you can feel the same with the <strong>Emilia Re:Zero artisan keycap</strong> on your keyboard.</p>\r\n\r\n<p>For more beautiful keycaps, visit us at this link.</p>\r\n\r\n<p>Tech Specs</p>\r\n\r\n<ul>\r\n	<li>Materials: Resin</li>\r\n	<li>Switch type: Compatible with Cherry MX switches &amp; clones</li>\r\n	<li>Size: 1u</li>\r\n	<li>Design and Handcrafted by Heroverse</li>\r\n</ul>\r\n\r\n<p>Inside the package</p>\r\n\r\n<ul>\r\n	<li>1 keycap by Heroverse</li>\r\n	<li>1 card</li>\r\n	<li>2 rubber finger gloves</li>\r\n</ul>\r\n\r\n<p>Sidenote</p>\r\n\r\n<ul>\r\n	<li>Every product was 100% handmade. The final product may vary slightly from the original photos. We would love to ask you to tolerate any reasonable differences.</li>\r\n	<li>For a long time use, please keep this product away from heat and water. Don’t soak it in the water. Wet tissue is acceptable.</li>\r\n	<li>We can make the keycaps in your chosen colors so please inform us.</li>\r\n</ul>', 'keycaps', 'anime-keycaps', '2025-12-16', '2025-12-16'),
('eye-of-sauron-lord-of-the-rings-knob', 'Eye Of Sauron Lord Of The Rings Knob', 'Top Product', 34.99, 0, 'Publish', 'https://heroverseart.sgp1.cdn.digitaloceanspaces.com/assets/images/7hGRThfz_Eye-of-sauron-lord-of-the-rings-knob-5.jpg', 'artisan keycap, keycap set, resin keycap, custom keycap, Keyboard Accessories, keycap resin, esc keycap, Evil Eye, Evil Eye keycap, Ring of Power, Eye of Sauron Keycap, Dark Lord Keycap, Lord of the Rings', '<p>Add a Magical Touch to Your Keyboard with Eye Of Sauron Lord of the Rings Knob</p>\r\n\r\n<p>Add a touch of Middle-earth magic to your setup with the <strong>Lord of the Rings\' Eye Of Sauron Knob for Keyboard</strong>. This handmade masterpiece is designed to capture the ominous allure of Sauron\'s gaze, bringing a unique and captivating element to your typing experience. Each Lord of the <strong>Rings\' Eye Of Sauron Knob</strong> is carefully crafted to ensure durability and a perfect fit, offering both aesthetic appeal and practical benefits.</p>\r\n\r\n<p>The<strong> Lord of the Rings\' Eye Of Sauron Knob for Keyboard</strong> not only enhances the visual appeal of your workspace but also provides a comfortable and satisfying feel with every keystroke. Ideal for fans and collectors, it’s a distinctive accessory that showcases your love for the iconic series.</p>\r\n\r\n<p>Ready to transform your keyboard? Discover more enchanting designs in our <a href=\"https://heroverseart.com/catalog?category=keyboard-knobs\">resin keyboard knob category</a> and find your perfect match.</p>\r\n\r\n<p><strong>Tech Specs:</strong></p>\r\n\r\n<ul>\r\n	<li>Switch type: Compatible with Cherry MX switches &amp; clones</li>\r\n	<li>Material: Resin</li>\r\n	<li>Backlit &amp; UV light support (Weak)</li>\r\n	<li>Design and Handcrafted by Heroverse</li>\r\n</ul>\r\n\r\n<p><strong>Inside the package:</strong></p>\r\n\r\n<ul>\r\n	<li>1 keycap by Heroverse</li>\r\n	<li>1 thank you card</li>\r\n	<li>2 rubber finger gloves</li>\r\n</ul>\r\n\r\n<p><strong>Sidenote:</strong></p>\r\n\r\n<ul>\r\n	<li>Every product was 100% handmade.</li>\r\n	<li>The final product may vary slightly from the original photos. We would love to ask you to tolerate any reasonable differences.</li>\r\n	<li>For a long time use, please keep this product away from heat and water. Simply use a damped tissue to clean the surface.</li>\r\n</ul>', 'keyboard-knobs', NULL, '2025-05-20', '2025-05-20'),
('galaxy-keyboard-knobs', 'Galaxy Keyboard Knobs', 'Best Product', 34.99, 0, 'Publish', 'https://heroverseart.sgp1.cdn.digitaloceanspaces.com/assets/images/VDkphuWU_Galaxy-keyboard-knobs-6-e1705046529813.jpg', 'hi75 knob, knob replacement, resin knob button, customize button, diy keyboard, backlit knob, water wave, biling biling, transparent liquid, gift for her, k81 knob, LEOBOG Hi75 gaming, computer accessory', '<p>keycaps you will fall in love with.</p>\r\n\r\n<p> </p>\r\n\r\n<p><strong>Tech Specs:</strong></p>\r\n\r\n<ul>\r\n	<li>Switch type: Compatible with Cherry MX switches &amp; clones</li>\r\n	<li>Material: Resin</li>\r\n	<li>Backlit &amp; UV light support (Weak)</li>\r\n	<li>Design and Handcrafted by Heroverse</li>\r\n</ul>\r\n\r\n<p><strong>Inside the package:</strong></p>\r\n\r\n<ul>\r\n	<li>1 keycap by Heroverse</li>\r\n	<li>1 thank you card</li>\r\n	<li>2 rubber finger gloves</li>\r\n</ul>\r\n\r\n<p><strong>Sidenote:</strong></p>\r\n\r\n<ul>\r\n	<li>Every product was 100% handmade.</li>\r\n	<li>The final product may vary slightly from the original photos. We would love to ask you to tolerate any reasonable differences.</li>\r\n	<li>For a long time use, please keep this product away from heat and water. Simply use a damped tissue to clean the surface. </li>\r\n</ul>\r\n\r\n<p>\"&gt;</p>', 'keyboard-knobs', NULL, '2025-05-20', '2025-05-20'),
('galaxy-personalized-serving-tray', 'Galaxy Personalized Serving Tray', 'Best Product', 67, 0, 'Publish', 'https://heroverseart.sgp1.cdn.digitaloceanspaces.com/assets/images/TOU0TWL2_galaxy-personalized-serving-tray-9.jpg', 'serving tray, cutting board, housewarming gift, epoxy resin tray, wedding hangers, wedding decoration, wedding portrait, wood tray, decorative tray, Gift for wife, perfume tray, tray decor, ceramic tray', '<p>Crafted from wood and resin epoxy, these items have been given a new purpose, transforming them into unique pieces for your living space. Each live edge black walnut and epoxy river charcuterie serving board, complete with metal handles, is one of a kind. Lubricated with harmless vegetable oil, these trays are suitable for food contact and can also serve as ottoman trays. As a natural product, each board varies in walnut wood grain and coloring, making every piece distinct.</p>\r\n\r\n<p>Tech specs:</p>\r\n\r\n<ul>\r\n	<li>Size M: 9\"x17\"x0.7\"</li>\r\n	<li>Size L: 11\"x22\"x0.7\"</li>\r\n	<li>Size XL: 13\"x28\"x0.7\"</li>\r\n	<li>0.5 inches in error</li>\r\n</ul>', 'resin-trays', NULL, '2025-05-20', '2025-05-20'),
('galaxy-resin-and-wood-wrist-rest', 'Galaxy Resin And Wood Wrist Rest', 'New Arrival', 59, 100, 'Publish', 'https://heroverseart.sgp1.cdn.digitaloceanspaces.com/assets/images/BGJddAYN_galaxy-wrist-rest-11.jpg-e1658205809838.jpg', 'keyboard wrist rest, Purple resin epoxy, moon wrist rest, handmade gift, birthday gift, office decor epoxy, gaming decor, anniversary gift, couples gift, Wrist rest galaxy, custom Wrist rest, art deco lamp, desk accessories', '<p> </p>\r\n\r\n<p>Galaxy wrist rest</p>\r\n\r\n<p>You can’t have the universe in your setup,  but that doesn’t mean you can’t pretend like it is. New from Heroverse, this Galaxy resin and wood wrist rest depicts a far-out scene in our galaxy. Handmade from colorful resin and encased in a transparent mold, the <a href=\"https://heroverseart.com/product/red-katana-resin-wrist-rest\">keyboard wrist rest</a> is friendly and soft to the touch, creating a smooth surface to support your wrists while you’re typing. </p>\r\n\r\n<p>Specs:</p>\r\n\r\n<p> </p>\r\n\r\n<ul>\r\n	<li>Size 60%: 30 x 1,5 x 2 (the thinnest place is 1.5 cm)</li>\r\n	<li>Size 65%: 32 x 1,5 x 2 (the thinnest place is 1.5 cm)</li>\r\n	<li>Size TKL: 36 x 1,5 x 2 (the thinnest place is 1.5 cm)</li>\r\n	<li>Full size: 44 x 1,5 x 2 (the thinnest place is 1.5 cm)</li>\r\n	<li>And we can make any custom size if you want.</li>\r\n	<li>Material: Wood and resin</li>\r\n	<li>Smooth, solvent-resistant polish for surface protection</li>\r\n</ul>\r\n\r\n<p>Inside the package:</p>\r\n\r\n<p> </p>\r\n\r\n<ul>\r\n	<li>1 wrist rest by Heroverse</li>\r\n	<li>1 card</li>\r\n</ul>\r\n\r\n<p>Sidenote:</p>\r\n\r\n<p> </p>\r\n\r\n<ul>\r\n	<li>Every product was 100% handmade. The final product may vary slightly from the original photos. We would love to ask you to tolerate any reasonable differences.</li>\r\n	<li>Easy-clean surface (simply use a damp cloth to wipe)</li>\r\n</ul>\r\n\r\n<p>\"&gt;</p>\r\n\r\n<p>\"&gt;</p>', 'wrist-rests', NULL, '2025-05-20', '2025-05-20'),
('galaxy-turtle-on-the-moon-night-light', 'Galaxy Turtle On The Moon Night Light', 'New Arrival', 59, 0, 'Publish', 'https://heroverseart.sgp1.cdn.digitaloceanspaces.com/assets/images/POt6OX99_Galaxy-turtle-on-the-moon-night-light-12.jpg', 'galaxy light, galaxy decor, epoxy lamp, astronaut lamp, custom night light, moon night light, resin night light, table lamp, standing lamp, night light lamp, baby night light, name night light, space night light', '<p><strong>Galactic Wonder in a Lamp - Discover the Galaxy Turtle on the Moon Night Light</strong></p>\r\n\r\n<p>You can enjoy the beauty of space in your own home by using a <strong>Galaxy Turtle on the Moon Night Light</strong>. Made for someone who loves dreaming and outer space, this handmade lamp lets you explore the mysteries of galaxies from your room.</p>\r\n\r\n<p>Witness a miniature moonlit spectacle as this enchanting turtle, adorned with a shell that mirrors the starry night sky, casts a soothing glow.</p>\r\n\r\n<p>Whether it\'s enhancing the ambiance of your bedroom or a cozy nook, the <strong>Galaxy Turtle on the Moon Epoxy Night Lamp</strong> invites you to lose yourself in its gentle, dreamlike radiance.</p>\r\n\r\n<p>The <strong>Galaxy Turtle on the Moon Resin Lamp</strong> is not just a light that can be customized to reflect your unique taste, it’s art that says you are pursued with everything about space.</p>\r\n\r\n<p>We have more <a href=\"https://heroverseart.com/catalog?category=epoxy-lamps\">epoxy lamps</a> available which will continue to carry you away into the abyss of the cosmos. The lighting up of our homes should go together with each heavenly beauty embodied in these lights.</p>\r\n\r\n<p>Tech specs:</p>\r\n\r\n<ul>\r\n	<li>Size L: 13cmx3.5cm(5.2\"x1.4\")</li>\r\n	<li>Size XL: 15cmx3.5cm(6\"x1.4\")</li>\r\n</ul>\r\n\r\n<p>Inside the package:</p>\r\n\r\n<ul>\r\n	<li>Handmade Night Light</li>\r\n	<li>USB cable for the light stand</li>\r\n</ul>', 'resin-lamps', 'anime-lamps', '2025-05-17', '2025-05-17'),
('game-of-thrones-resin-wrist-rest', 'Game Of Thrones Resin Wrist Rest', 'New Arrival', 59, 119, 'Publish', 'https://heroverseart.sgp1.cdn.digitaloceanspaces.com/assets/images/uPDrRVRM_game-of-thrones-wrist-rest-5.jpg', '18th birthday gift, resin wrist rest, custom wrist rest, back to school, galaxy keycap, galaxy crystal, gamer girl gifts, gamer gifts for him, gamer gift box, boyfriend graduation, galaxy space, keyboard wrist rest, astronaut gift', '<p>Bring Game of Thrones powerful weapon to your keyboard with Game of Thrones Resin Wrist Rest</p>\r\n\r\n<p> </p>\r\n\r\n<p>Game of Thrones is truly a great blockbuster of all time. The show is not just about fantasy. It also hits us on other levels, such as how it asks us to get to know the characters and their backgrounds. It teaches us that there is no such thing as a straight answer.</p>\r\n\r\n<p><img alt=\"Game of thrones resin wrist rest\" src=\"https://i0.wp.com/hirosarts.com/wp-content/uploads/2022/04/game-of-thrones-wrist-rest-8.jpg?resize=665%2C465&amp;ssl=1\"></p>\r\n\r\n<p>Game of thrones wrist rest</p>\r\n\r\n<p>It’s the inspiration. Now it comes to you inside a Game of Thrones resin wrist rest. Every detail gets sculpted exactly to millimeters. Game of Thrones sword is cast in resin, like a sleeping treasure. Now you feel the sharpness and balance of the weapon supporting your forearm. That’s amazing.</p>\r\n\r\n<p><img alt=\"Game of thrones resin wrist rest\" src=\"https://i0.wp.com/hirosarts.com/wp-content/uploads/2022/04/game-of-thrones-wrist-rest-3.jpg?resize=609%2C411&amp;ssl=1\"></p>\r\n\r\n<p>Game of thrones wrist rest</p>\r\n\r\n<p>This Game of Thrones Wrist Rest will be a great gift for anyone who is a huge fan of the show. It\'s made from high-quality materials and it takes a lot of time to make. You can really feel the quality once touching this stunning <a href=\"https://heroverseart.com/catalog?category=wrist-rests\">artisan wrist rest</a> in person. It\'s ideal for relaxing and inspiring while working.</p>\r\n\r\n<p>Get your workspace refreshed and personalize with this cool design of keyboard wrist rest! Soothing gel comfort encourages neutral wrist posture. Clear gel is easy to keep clean. The nonskid base will keep the wrist rest in place. </p>\r\n\r\n<p>Specs:</p>\r\n\r\n<p> </p>\r\n\r\n<ul>\r\n	<li>Size 60%: 30 x 1,5 x 2 (the thinnest place is 1.5 cm)</li>\r\n	<li>Size 65%: 32 x 1,5 x 2 (the thinnest place is 1.5 cm)</li>\r\n	<li>Size TKL: 36 x 1,5 x 2 (the thinnest place is 1.5 cm)</li>\r\n	<li>Full size: 44 x 1,5 x 2 (the thinnest place is 1.5 cm)</li>\r\n	<li>And we can make any custom size if you want.</li>\r\n	<li>Material: Wood and resin</li>\r\n	<li>Smooth, solvent-resistant polish for surface protection</li>\r\n</ul>\r\n\r\n<p>Inside the package:</p>\r\n\r\n<p> </p>\r\n\r\n<ul>\r\n	<li>1 wrist rest by Heroverse</li>\r\n	<li>1 card</li>\r\n</ul>\r\n\r\n<p>Sidenote:</p>\r\n\r\n<p> </p>\r\n\r\n<ul>\r\n	<li>Every product was 100% handmade. The final product may vary slightly from the original photos. We would love to ask you to tolerate any reasonable differences.</li>\r\n	<li>Easy-clean surface (simply use a damp cloth to wipe)</li>\r\n</ul>', 'wrist-rests', NULL, '2025-05-20', '2025-05-20'),
('gengar-keyboard-wrist-rest', 'Gengar Keyboard Wrist Rest', NULL, 68.99, 89.99, 'Publish', 'https://heroverseart.sgp1.cdn.digitaloceanspaces.com/assets/images/AcToS8sQ_Wrist-rest-28.jpg-e1689955973563.jpg', '18th birthday gift, resin wrist rest, custom wrist rest, back to school, gamer girl gifts, gamer gifts for him, gamer gift box, keyboard wrist rest, astronaut gift, Wrist rest, gamer gift, laptop wrist rest, Wooden keyboard, Wooden wrist rest, computer keyboard, keyboard pad, keyboard wrist pad, mechanical keyboard, wooden palm rest, wooden', '<p>Immerse yourself in the haunting world of Gengar with Gengar Keyboard Wrist Rest</p>\r\n\r\n<p> </p>\r\n\r\n<p>Experience the thrill right from the start as you rest your wrists on the Gengar Keyboard Wrist Rest. Let Gengar\'s eerie charm and playful energy enhance your gaming experience with a touch of supernatural flair.</p>\r\n\r\n<p><img alt=\"Gengar keyboard wrist rest\" src=\"https://i0.wp.com/hirosarts.com/wp-content/uploads/2023/05/Wrist-rest-3-1.jpg-1.jpg?resize=300%2C300&amp;ssl=1\"></p>\r\n\r\n<p>Gengar keyboard wrist rest</p>\r\n\r\n<p>Indulge in the ergonomic design of the Gengar Keyboard Wrist Rest, providing optimal comfort and support during intense gaming sessions. Let Gengar be your trusted companion, warding off discomfort and allowing you to stay focused on the game.</p>\r\n\r\n<p>Don\'t miss out on the opportunity to own the Gengar Keyboard Wrist Rest. Click now to embrace the mischievous allure of Gengar and elevate your gaming setup to new heights. Unleash your gaming potential and click below to make it yours today.</p>\r\n\r\n<p>Specs:</p>\r\n\r\n<p> </p>\r\n\r\n<ul>\r\n	<li>60%: 300mm x 80mm</li>\r\n	<li>65%: 320mm x 80mm</li>\r\n	<li>TKL: 360mmx80mm</li>\r\n	<li>Fullsize: 440mmx80mm</li>\r\n	<li>And we can make any custom size if you want.</li>\r\n	<li>Material: Wood and resin</li>\r\n	<li>Smooth, solvent-resistant polish for surface protection</li>\r\n</ul>\r\n\r\n<p>Inside the package:</p>\